				if (node0.Tag is > 0 and < 957)
				{
					var bit = 1UL << (node0.Tag & 63);

					if ((seen0[node0.Tag >> 6] & bit) != 0)
						(found ??= []).Add(new FixFinding(FixRule.DuplicateField, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The tag appears more than once in this scope."));

					seen0[node0.Tag >> 6] |= bit;
				}
				else if (!(extended0 ??= []).Add(node0.Tag))
					(found ??= []).Add(new FixFinding(FixRule.DuplicateField, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The tag appears more than once in this scope."));

				FixStandard.Pair(scope0, i0, FixScope.Header, 0, -1, ref found);

				switch (node0.Tag)
				{
					case 8:   // BeginString, String
						if (!FixPrimitives.Valid(field0, FixValueType.String, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

