						if (!FixPrimitives.Valid(field0, FixValueType.String, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 129:   // DeliverToSubID, String
						if (!FixPrimitives.Valid(field0, FixValueType.String, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 145:   // DeliverToLocationID, String
						if (!FixPrimitives.Valid(field0, FixValueType.String, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 43:   // PossDupFlag, Boolean
						if (!FixPrimitives.Valid(field0, FixValueType.Boolean, FixCodes.T43))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 97:   // PossResend, Boolean
						if (!FixPrimitives.Valid(field0, FixValueType.Boolean, FixCodes.T97))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 52:   // SendingTime, UTCTimestamp
						if (!FixPrimitives.Valid(field0, FixValueType.UTCTimestamp, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 122:   // OrigSendingTime, UTCTimestamp
						if (!FixPrimitives.Valid(field0, FixValueType.UTCTimestamp, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 212:   // XmlDataLen, Length
						if (!FixPrimitives.Valid(field0, FixValueType.Length, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 213:   // XmlData, data
						if (!FixPrimitives.Valid(field0, FixValueType.Data, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 347:   // MessageEncoding, String
						if (!FixPrimitives.Valid(field0, FixValueType.String, FixCodes.T347))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 369:   // LastMsgSeqNumProcessed, SeqNum
						if (!FixPrimitives.Valid(field0, FixValueType.SeqNum, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 627:   // NoHops, NumInGroup
						if (!FixPrimitives.Valid(field0, FixValueType.NumInGroup, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					default:
						FixStandard.NotInScope(field0, FixScope.Header, 0, -1, ref found);
						break;
				}
			}

			// BeginString, tag 8, which this scope requires
			if (!((seen0[0] & 0x0000000000000100UL) != 0))
				(found ??= []).Add(new FixFinding(FixRule.RequiredFieldMissing, FixScope.Header, 8, 0, -1, 0, "The schema requires this tag in this scope."));

			// BodyLength, tag 9, which this scope requires
			if (!((seen0[0] & 0x0000000000000200UL) != 0))
				(found ??= []).Add(new FixFinding(FixRule.RequiredFieldMissing, FixScope.Header, 9, 0, -1, 0, "The schema requires this tag in this scope."));

			// MsgType, tag 35, which this scope requires
			if (!((seen0[0] & 0x0000000800000000UL) != 0))
				(found ??= []).Add(new FixFinding(FixRule.RequiredFieldMissing, FixScope.Header, 35, 0, -1, 0, "The schema requires this tag in this scope."));

			// SenderCompID, tag 49, which this scope requires
			if (!((seen0[0] & 0x0002000000000000UL) != 0))
				(found ??= []).Add(new FixFinding(FixRule.RequiredFieldMissing, FixScope.Header, 49, 0, -1, 0, "The schema requires this tag in this scope."));

			// TargetCompID, tag 56, which this scope requires
			if (!((seen0[0] & 0x0100000000000000UL) != 0))
				(found ??= []).Add(new FixFinding(FixRule.RequiredFieldMissing, FixScope.Header, 56, 0, -1, 0, "The schema requires this tag in this scope."));

			// MsgSeqNum, tag 34, which this scope requires
			if (!((seen0[0] & 0x0000000400000000UL) != 0))
				(found ??= []).Add(new FixFinding(FixRule.RequiredFieldMissing, FixScope.Header, 34, 0, -1, 0, "The schema requires this tag in this scope."));

			// SendingTime, tag 52, which this scope requires
			if (!((seen0[0] & 0x0010000000000000UL) != 0))
				(found ??= []).Add(new FixFinding(FixRule.RequiredFieldMissing, FixScope.Header, 52, 0, -1, 0, "The schema requires this tag in this scope."));

			// the group Hop, counted by tag 627
			if (!((seen0[9] & 0x0008000000000000UL) != 0))
			{
				// the schema does not require this group
			}
			else
			{
				var counter0 = scope0.GetField(627)!.Value;
				var entries0 = scope0.GetGroup(627);

				if (!counter0.TryGetInt64(out var count0) || count0 != entries0.Count || count0 < 0)
					(found ??= []).Add(new FixFinding(FixRule.GroupCountMismatch, FixScope.Header, counter0.Tag, 0, -1, counter0.ValuePosition,
						$"The count says {counter0} and {entries0.Count} entries follow."));

				var index0 = 0;

				foreach (var one0 in entries0)
				{
					{
						var scope1 = one0;
						var seen1 = new ulong[15];
						HashSet<int>? extended1 = null;
						var rank1 = -1;

						for (var i1 = 0; i1 < scope1.Nodes.Length; i1++)
						{
							var node1  = scope1.Nodes[i1];
							var field1 = node1.Field(scope1.Source);

							// an entry's fields come in the order the schema lists them
							switch (node1.Tag)
							{
								case 628:   // HopCompID
									if (0 < rank1)
										(found ??= []).Add(new FixFinding(FixRule.FieldOutOfOrder, FixScope.Header, field1.Tag, 627, index0, field1.ValuePosition, "The fields of a group entry are not in the order the schema gives them."));
									else
										rank1 = 0;

									break;

								case 629:   // HopSendingTime
									if (1 < rank1)
										(found ??= []).Add(new FixFinding(FixRule.FieldOutOfOrder, FixScope.Header, field1.Tag, 627, index0, field1.ValuePosition, "The fields of a group entry are not in the order the schema gives them."));
									else
										rank1 = 1;

									break;

								case 630:   // HopRefID
									if (2 < rank1)
										(found ??= []).Add(new FixFinding(FixRule.FieldOutOfOrder, FixScope.Header, field1.Tag, 627, index0, field1.ValuePosition, "The fields of a group entry are not in the order the schema gives them."));
									else
										rank1 = 2;

									break;

							}

							// the tag twice in one scope
							if (node1.Tag is > 0 and < 957)
							{
								var bit = 1UL << (node1.Tag & 63);

								if ((seen1[node1.Tag >> 6] & bit) != 0)
									(found ??= []).Add(new FixFinding(FixRule.DuplicateField, FixScope.Header, field1.Tag, 627, index0, field1.ValuePosition, "The tag appears more than once in this scope."));

								seen1[node1.Tag >> 6] |= bit;
							}
							else if (!(extended1 ??= []).Add(node1.Tag))
								(found ??= []).Add(new FixFinding(FixRule.DuplicateField, FixScope.Header, field1.Tag, 627, index0, field1.ValuePosition, "The tag appears more than once in this scope."));

							FixStandard.Pair(scope1, i1, FixScope.Header, 627, index0, ref found);

							switch (node1.Tag)
							{
								case 628:   // HopCompID, String
									if (!FixPrimitives.Valid(field1, FixValueType.String, null))
										(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field1.Tag, 627, index0, field1.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

									break;

								case 629:   // HopSendingTime, UTCTimestamp
									if (!FixPrimitives.Valid(field1, FixValueType.UTCTimestamp, null))
										(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field1.Tag, 627, index0, field1.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

									break;

								case 630:   // HopRefID, SeqNum
									if (!FixPrimitives.Valid(field1, FixValueType.SeqNum, null))
										(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Header, field1.Tag, 627, index0, field1.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

									break;

								default:
									FixStandard.NotInScope(field1, FixScope.Header, 627, index0, ref found);
									break;
							}
						}
					}

					index0++;
				}
			}
		}
	}

	/// <summary>The standard trailer, which every message carries.</summary>
	public static void Trailer(FixMessage message, ref List<FixFinding>? found)
	{
		{
			var scope0 = message.Trailer;
			var seen0 = new ulong[15];
			HashSet<int>? extended0 = null;

			for (var i0 = 0; i0 < scope0.Nodes.Length; i0++)
			{
				var node0  = scope0.Nodes[i0];
				var field0 = node0.Field(scope0.Source);

				// the tag twice in one scope
				if (node0.Tag is > 0 and < 957)
				{
					var bit = 1UL << (node0.Tag & 63);

					if ((seen0[node0.Tag >> 6] & bit) != 0)
						(found ??= []).Add(new FixFinding(FixRule.DuplicateField, FixScope.Trailer, field0.Tag, 0, -1, field0.ValuePosition, "The tag appears more than once in this scope."));

					seen0[node0.Tag >> 6] |= bit;
				}
				else if (!(extended0 ??= []).Add(node0.Tag))
					(found ??= []).Add(new FixFinding(FixRule.DuplicateField, FixScope.Trailer, field0.Tag, 0, -1, field0.ValuePosition, "The tag appears more than once in this scope."));

				FixStandard.Pair(scope0, i0, FixScope.Trailer, 0, -1, ref found);

				switch (node0.Tag)
				{
					case 93:   // SignatureLength, Length
						if (!FixPrimitives.Valid(field0, FixValueType.Length, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Trailer, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 89:   // Signature, data
						if (!FixPrimitives.Valid(field0, FixValueType.Data, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Trailer, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					case 10:   // CheckSum, String
						if (!FixPrimitives.Valid(field0, FixValueType.String, null))
							(found ??= []).Add(new FixFinding(FixRule.InvalidValue, FixScope.Trailer, field0.Tag, 0, -1, field0.ValuePosition, "The value does not fit the field's type, or is not one of its code set."));

						break;

					default:
						FixStandard.NotInScope(field0, FixScope.Trailer, 0, -1, ref found);
						break;
				}
			}

			// CheckSum, tag 10, which this scope requires
			if (!((seen0[0] & 0x0000000000000400UL) != 0))
				(found ??= []).Add(new FixFinding(FixRule.RequiredFieldMissing, FixScope.Trailer, 10, 0, -1, 0, "The schema requires this tag in this scope."));
		}
	}

	/// <summary>MessageEncoding, which an Encoded field cannot be read without.</summary>
	public static void Encoding(FixMessage message, ref List<FixFinding>? found)
	{
		if (message.Header.GetField(347) == null && (Encoded(message.Header) || Encoded(message)))
			(found ??= []).Add(new FixFinding(FixRule.MessageEncodingMissing, FixScope.Header, 347, 0, -1, 0,
				"MessageEncoding is required where an Encoded field is present."));
	}

	static bool Encoded(FixFieldSet scope)
	{
		foreach (var node in scope.Nodes)
		{
			switch (node.Tag)
			{
				case 349:   // EncodedIssuer
				case 351:   // EncodedSecurityDesc
				case 353:   // EncodedListExecInst
				case 355:   // EncodedText
				case 357:   // EncodedSubject
				case 359:   // EncodedHeadline
				case 361:   // EncodedAllocText
				case 363:   // EncodedUnderlyingIssuer
				case 365:   // EncodedUnderlyingSecurityDesc
				case 446:   // EncodedListStatusText
				case 619:   // EncodedLegIssuer
				case 622:   // EncodedLegSecurityDesc
					return true;
			}

			if (node.Entries != null)
				foreach (var entry in node.Entries)
					if (Encoded(entry))
						return true;
		}

		return false;
	}

	/// <summary>A data field follows the length that measures it, and a length precedes it.</summary>
	/// <remarks>
	/// The sixteen pairs of FIX 4.4, asked of every field of every scope. Which tags are a
	/// pair is the standard's answer and the same in every message, so it is written here
	/// once; a pair is read off the wire as ONE field carrying the data tag, and these two
	/// findings are about the length field that should have stood beside it.
	/// </remarks>
	public static void Pair(FixFieldSet scope, int index, FixScope where, int groupTag, int entry, ref List<FixFinding>? found)
	{
		switch (scope.Nodes[index].Tag)
		{
			case 89:   // Signature, which tag 93 measures
				AfterLength(scope, index, 93, where, groupTag, entry, ref found);
				break;

			case 91:   // SecureData, which tag 90 measures
				AfterLength(scope, index, 90, where, groupTag, entry, ref found);
				break;

			case 96:   // RawData, which tag 95 measures
				AfterLength(scope, index, 95, where, groupTag, entry, ref found);
				break;

			case 213:   // XmlData, which tag 212 measures
				AfterLength(scope, index, 212, where, groupTag, entry, ref found);
				break;

			case 349:   // EncodedIssuer, which tag 348 measures
				AfterLength(scope, index, 348, where, groupTag, entry, ref found);
				break;

			case 351:   // EncodedSecurityDesc, which tag 350 measures
				AfterLength(scope, index, 350, where, groupTag, entry, ref found);
				break;

			case 353:   // EncodedListExecInst, which tag 352 measures
				AfterLength(scope, index, 352, where, groupTag, entry, ref found);
				break;

			case 355:   // EncodedText, which tag 354 measures
				AfterLength(scope, index, 354, where, groupTag, entry, ref found);
				break;

			case 357:   // EncodedSubject, which tag 356 measures
				AfterLength(scope, index, 356, where, groupTag, entry, ref found);
				break;

			case 359:   // EncodedHeadline, which tag 358 measures
				AfterLength(scope, index, 358, where, groupTag, entry, ref found);
				break;

			case 361:   // EncodedAllocText, which tag 360 measures
				AfterLength(scope, index, 360, where, groupTag, entry, ref found);
				break;

			case 363:   // EncodedUnderlyingIssuer, which tag 362 measures
				AfterLength(scope, index, 362, where, groupTag, entry, ref found);
				break;

			case 365:   // EncodedUnderlyingSecurityDesc, which tag 364 measures
				AfterLength(scope, index, 364, where, groupTag, entry, ref found);
				break;

			case 446:   // EncodedListStatusText, which tag 445 measures
				AfterLength(scope, index, 445, where, groupTag, entry, ref found);
				break;

			case 619:   // EncodedLegIssuer, which tag 618 measures
				AfterLength(scope, index, 618, where, groupTag, entry, ref found);
				break;

			case 622:   // EncodedLegSecurityDesc, which tag 621 measures
				AfterLength(scope, index, 621, where, groupTag, entry, ref found);
				break;

			case 90:   // SecureDataLen, which measures tag 91
				BeforeData(scope, index, 91, where, groupTag, entry, ref found);
				break;

			case 93:   // SignatureLength, which measures tag 89
				BeforeData(scope, index, 89, where, groupTag, entry, ref found);
				break;

			case 95:   // RawDataLength, which measures tag 96
				BeforeData(scope, index, 96, where, groupTag, entry, ref found);
				break;

			case 212:   // XmlDataLen, which measures tag 213
				BeforeData(scope, index, 213, where, groupTag, entry, ref found);
				break;

			case 348:   // EncodedIssuerLen, which measures tag 349
				BeforeData(scope, index, 349, where, groupTag, entry, ref found);
				break;

			case 350:   // EncodedSecurityDescLen, which measures tag 351
				BeforeData(scope, index, 351, where, groupTag, entry, ref found);
				break;

			case 352:   // EncodedListExecInstLen, which measures tag 353
				BeforeData(scope, index, 353, where, groupTag, entry, ref found);
				break;

			case 354:   // EncodedTextLen, which measures tag 355
				BeforeData(scope, index, 355, where, groupTag, entry, ref found);
				break;

			case 356:   // EncodedSubjectLen, which measures tag 357
				BeforeData(scope, index, 357, where, groupTag, entry, ref found);
				break;

			case 358:   // EncodedHeadlineLen, which measures tag 359
				BeforeData(scope, index, 359, where, groupTag, entry, ref found);
				break;

			case 360:   // EncodedAllocTextLen, which measures tag 361
				BeforeData(scope, index, 361, where, groupTag, entry, ref found);
				break;

			case 362:   // EncodedUnderlyingIssuerLen, which measures tag 363
				BeforeData(scope, index, 363, where, groupTag, entry, ref found);
				break;

			case 364:   // EncodedUnderlyingSecurityDescLen, which measures tag 365
				BeforeData(scope, index, 365, where, groupTag, entry, ref found);
				break;

			case 445:   // EncodedListStatusTextLen, which measures tag 446
				BeforeData(scope, index, 446, where, groupTag, entry, ref found);
				break;

			case 618:   // EncodedLegIssuerLen, which measures tag 619
				BeforeData(scope, index, 619, where, groupTag, entry, ref found);
				break;

			case 621:   // EncodedLegSecurityDescLen, which measures tag 622
				BeforeData(scope, index, 622, where, groupTag, entry, ref found);
				break;

		}
	}

	static void AfterLength(FixFieldSet scope, int index, int lengthTag, FixScope where, int groupTag, int entry, ref List<FixFinding>? found)
	{
		var node = scope.Nodes[index];

		if (index == 0 ||
			scope.Nodes[index - 1].Tag != lengthTag ||
			!scope.Nodes[index - 1].Field(scope.Source).TryGetInt64(out var measured) ||
			measured != node.Length)
		{
			var field = node.Field(scope.Source);

			(found ??= []).Add(new FixFinding(FixRule.DataFieldNotAfterLength, where, field.Tag, groupTag, entry, field.ValuePosition,
				$"A data field must immediately follow tag {lengthTag}, which measures it."));
		}
	}

	static void BeforeData(FixFieldSet scope, int index, int dataTag, FixScope where, int groupTag, int entry, ref List<FixFinding>? found)
	{
		if (index + 1 == scope.Nodes.Length || scope.Nodes[index + 1].Tag != dataTag)
		{
			var field = scope.Nodes[index].Field(scope.Source);

			(found ??= []).Add(new FixFinding(FixRule.LengthFieldNotBeforeData, where, field.Tag, groupTag, entry, field.ValuePosition,
				$"A length field must immediately precede tag {dataTag}, which it measures."));
		}
	}

	/// <summary>A tag the scope does not list, and the two sentences that tells apart.</summary>
	/// <remarks>
	/// Whether FIX 4.4 defines a tag at all is a question about the standard and the same for
	/// every scope, which is why it is asked here rather than written into each of them.
	/// </remarks>
	public static void NotInScope(FixFieldView field, FixScope where, int groupTag, int entry, ref List<FixFinding>? found)
	{
		(found ??= []).Add(new FixFinding(FixRule.FieldNotInScope, where, field.Tag, groupTag, entry, field.ValuePosition,
			Defines(field.Tag)
				? "The schema defines this tag, but not in this scope."
				: "The schema defines no such tag."));
	}

